import sys, os
out=[]
for mod in ['PIL','numpy','scipy','skimage','matplotlib']:
    try:
        m=__import__(mod); out.append(mod+' '+getattr(m,'__version__','?'))
    except Exception as e: out.append(mod+' ERR '+repr(e))
for p in ['/usr/share/fonts','/opt/conda/fonts','/usr/local/lib/python3.11/site-packages/matplotlib/mpl-data/fonts/ttf','/usr/local/lib/python3.12/site-packages/matplotlib/mpl-data/fonts/ttf','/usr/share/fonts/truetype/dejavu']:
    try:
        out.append(p+' dir='+str(os.path.isdir(p))+' files='+repr(os.listdir(p)[:8]) if os.path.isdir(p) else p+' absent')
    except Exception as e: out.append(p+' ERR '+repr(e))
open('probe.txt','w').write('\n'.join(out)+'\n')
PY
